/**
 * Rows the CoasterTrak site hides from its public catalog. The quality report skips them so
 * every run does not re-flag rows that were hidden on purpose.
 *
 * The rules are data generated by CoasterTrak (src/lib/catalog-hidden-rules.ts) and committed
 * here as catalog-hidden-rules.json. Do not edit the JSON by hand: change the tables in
 * CoasterTrak, then run `npx tsx scripts/export-catalog-hidden-rules.ts` there. CoasterTrak's
 * catalog-quality pipeline re-exports it before every analyze run.
 *
 * Only the regex parts of CoasterTrak's isCatalogHiddenParkName are mirrored as code below;
 * the JSON carries example names with CoasterTrak's answers and the tests check this mirror
 * against every one of them.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { z } from "zod";

import type { CanonicalCoaster } from "../canonical/coaster.js";
import type { CanonicalPark } from "../canonical/park.js";
import { resolveCoasterDbId } from "../lib/public-links.js";

export const catalogHiddenRulesSchema = z.object({
  version: z.literal(1),
  skipWikidataCoasterIds: z.array(z.string()),
  misattributedRows: z.record(z.string(), z.array(z.string())),
  nonCoasterRows: z.record(z.string(), z.array(z.string())),
  placeholderParkNames: z.array(z.string()),
  hiddenParkNameExamples: z.array(z.object({ name: z.string(), hidden: z.boolean() })),
});

export type CatalogHiddenRules = z.infer<typeof catalogHiddenRulesSchema>;

export const DEFAULT_CATALOG_HIDDEN_RULES_PATH = fileURLToPath(
  new URL("./catalog-hidden-rules.json", import.meta.url),
);

export function loadCatalogHiddenRules(
  path: string = DEFAULT_CATALOG_HIDDEN_RULES_PATH,
): CatalogHiddenRules {
  const raw: unknown = JSON.parse(readFileSync(path, "utf8"));
  const parsed = catalogHiddenRulesSchema.safeParse(raw);
  if (!parsed.success) {
    throw new Error(`Invalid catalog hidden-row rules at ${path}: ${parsed.error.message}`);
  }
  return parsed.data;
}

let defaultRules: CatalogHiddenRules | null = null;

/** The committed rules, read once. */
export function defaultCatalogHiddenRules(): CatalogHiddenRules {
  defaultRules ??= loadCatalogHiddenRules();
  return defaultRules;
}

// --- Mirror of CoasterTrak park-match.ts / geo-country.ts / wikidata-qid.ts -------------

function unjamGeoLabel(raw: string): string {
  return raw
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/\s+/g, " ")
    .trim();
}

/** Legacy multi-city location blobs stored as park names. */
function isJammedMultiLocationParkName(raw: string): boolean {
  if (!/[a-z][A-Z]/.test(raw)) return false;
  const unjammed = unjamGeoLabel(raw).toLowerCase();
  const placeHits = (
    unjammed.match(
      /\b(florida|california|georgia|texas|ohio|carolina|york|jersey|united states|u\.?s\.?a?\.?)\b/g,
    ) ?? []
  ).length;
  return placeHits >= 2 || (raw.includes(",") && placeHits >= 1);
}

/**
 * Placeholder parks ("Other", "Unknown / historical park (…)", bare Q-ids, location blobs)
 * that CoasterTrak keeps out of the catalog, with everything on them.
 */
export function isCatalogHiddenParkName(
  name: string | null | undefined,
  rules: CatalogHiddenRules = defaultCatalogHiddenRules(),
): boolean {
  const parkName = (name ?? "").trim();
  if (!parkName) return true;
  if (rules.placeholderParkNames.includes(parkName.toLowerCase())) return true;
  if (/^Q\d+$/i.test(parkName)) return true;
  if (isJammedMultiLocationParkName(parkName)) return true;
  return /^unknown\s*\/\s*historical park/i.test(parkName);
}

// --- Row filter ---------------------------------------------------------------------------

export type HiddenRowReason =
  "skipped_wikidata_id" | "placeholder_park" | "misattributed_row" | "not_a_coaster";

export type HiddenCoasterRow = {
  id: string;
  dbId: number | null;
  name: string;
  parkName: string | null;
  reason: HiddenRowReason;
};

export function hiddenCoasterReason(
  coaster: CanonicalCoaster,
  park: CanonicalPark | null | undefined,
  rules: CatalogHiddenRules = defaultCatalogHiddenRules(),
): HiddenRowReason | null {
  const qid = coaster.sourceIds.wikidata?.trim().toUpperCase();
  if (qid && rules.skipWikidataCoasterIds.includes(qid)) return "skipped_wikidata_id";
  // A coaster with no park is a data problem the report should keep flagging.
  if (!park) return null;
  const parkName = park.name.value;
  if (isCatalogHiddenParkName(parkName, rules)) return "placeholder_park";
  const name = coaster.name.value;
  if (rules.misattributedRows[parkName]?.includes(name)) return "misattributed_row";
  if (rules.nonCoasterRows[parkName]?.includes(name)) return "not_a_coaster";
  return null;
}

export type CatalogHiddenFilterResult = {
  parks: CanonicalPark[];
  coasters: CanonicalCoaster[];
  hiddenParks: { id: string; name: string }[];
  hiddenCoasters: HiddenCoasterRow[];
};

/** Split the catalog into what the site shows (analyzed) and what it hides (skipped). */
export function filterCatalogHiddenRows(
  parks: CanonicalPark[],
  coasters: CanonicalCoaster[],
  rules: CatalogHiddenRules = defaultCatalogHiddenRules(),
): CatalogHiddenFilterResult {
  const parksById = new Map(parks.map((p) => [p.id, p]));
  const keptParks: CanonicalPark[] = [];
  const hiddenParks: CatalogHiddenFilterResult["hiddenParks"] = [];
  for (const park of parks) {
    if (isCatalogHiddenParkName(park.name.value, rules)) {
      hiddenParks.push({ id: park.id, name: park.name.value });
    } else {
      keptParks.push(park);
    }
  }

  const keptCoasters: CanonicalCoaster[] = [];
  const hiddenCoasters: HiddenCoasterRow[] = [];
  for (const coaster of coasters) {
    const park = coaster.parkId ? parksById.get(coaster.parkId) : null;
    const reason = hiddenCoasterReason(coaster, park, rules);
    if (reason) {
      hiddenCoasters.push({
        id: coaster.id,
        dbId: resolveCoasterDbId(coaster.sourceIds, coaster.id),
        name: coaster.name.value,
        parkName: park?.name.value ?? null,
        reason,
      });
    } else {
      keptCoasters.push(coaster);
    }
  }

  return { parks: keptParks, coasters: keptCoasters, hiddenParks, hiddenCoasters };
}
